// 利用模板类写链表：
#include <iostream>

	template <typename T>
	class Node {
	public:
		T data;
		Node<T>* next;

		Node(T value) : data(value), next(nullptr) {}
	};

	template <typename T>
	class LinkedList {
	private:
		Node<T>* head;
		Node<T>* tail;
	public:
		LinkedList() : head(nullptr), tail(nullptr) {}

		void insert(T value) {
			Node<T>* newNode = new Node<T>(value);
			if (head == nullptr) {
				head = tail = newNode;
			}
			else {
				tail->next = newNode;
				tail = newNode;
			}
		}

		void display() {
			Node<T>* current = head;
			while (current != nullptr) {
				std::cout << current->data << std::endl;
				current = current->next;
			}
		}
	};
	//这样就生成了一个先输入长度,再输入内容的链表
	int main() {
		int length;
		std::cin >> length;

		LinkedList<int> myList;

		for (int i = 0; i < length; ++i) {
			int value;
			std::cin >> value;
			myList.insert(value);
		}

		myList.display();

		return 0;
	}
