#include<iostream>
using namespace std;
class Complex
{
public:
	Complex() {};
	Complex(double a, double b)
	{
		Real = a;
		Image = b;
	}
	// TODO: 重载 ==
	bool operator==(Complex c)
	{
		if (Real == c.Real&&Image == c.Image)
		{
			return 1;
		}
		else
		{
			return 0;
		}
	}
	// TODO: 重载 !=
	bool operator!=(Complex c)
	{
		if (Real == c.Real&&Image == c.Image)
		{
			return 0;
		}
		else
		{
			return 1;
		}
	}
	// TODO: 重载 -
	Complex operator-()
	{
		Complex c0;
		c0.Image = -Image;
		c0.Real = -Real;
		return c0;
	}
	// TODO: 重载 >>
	friend ostream& operator>>(ostream &cout, Complex &c);

private:
	double  Real, Image;
};
ostream& operator>>(ostream &cout, Complex &c)
{
	cout << "(" << c.Real << " + " << c.Image << "i)";
	return cout;
}

