int read() {
    int x = 0;
    char c = getchar();
    while (c < '0' || c > '9') {
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + c - '0';
        c = getchar();
    }
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = read(), k = read();
    vector<int> a(n), b(n);

    // 读取A数组
    for(int i = 0; i < n; i++) {
        a[i] = read();
    }

    // 读取B数组
    for(int i = 0; i < n; i++) {
        b[i] = read();
    }

    // 使用nth_element来找到前k大的元素
    vector<int> indices(n);
    for(int i = 0; i < n; i++) {
        indices[i] = i;
    }

    nth_element(indices.begin(), indices.begin() + k, indices.end(),
        [&](int i, int j) {
            return (b[i] - a[i]) > (b[j] - a[j]);
        });

    long long ans = 0;
    // 选择差值最大的k个课程翘课
    for(int i = 0; i < n; i++) {
        if(i < k) {
            ans += b[indices[i]];
        } else {
            ans += a[indices[i]];
        }
    }

    cout << ans << endl;
    return 0;
}

