#include <iostream>
#include <queue>
#include <vector>
using namespace std;
using ll = long long;

const int MAXN = 105;
ll f[MAXN], d[MAXN], t[MAXN];
int n, h;

// 计算在某个果树停留k个5分钟能获得的果子数量
ll get_fruits(int tree, int k) {
    ll total = 0;
    ll current = f[tree];
    for (int i = 0; i < k; i++) {
        total += current;
        current = max(0LL, current - d[tree]);
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> h;
    for (int i = 1; i <= n; i++) cin >> f[i];
    for (int i = 1; i <= n; i++) cin >> d[i];
    for (int i = 1; i < n; i++) cin >> t[i];

    // 将小时转换为5分钟的倍数
    h = h * 12;  // 1小时 = 12个5分钟

    ll ans = 0;
    // 枚举结束的果树
    for (int end = 1; end <= n; end++) {
        // 计算到达end果树需要的时间
        ll walk_time = 0;
        for (int i = 1; i < end; i++) {
            walk_time += t[i];
        }

        // 如果走路时间超过总时间，跳过
        if (walk_time >= h) continue;

        // 剩余可以摘果子的时间
        ll remain_time = h - walk_time;

        // 使用优先队列存储每个果树当前能获得的最大果子数
        priority_queue<pair<ll, pair<int, int>>> pq;
        // pair<ll, pair<int, int>> 表示 {当前能获得的果子数, {果树编号, 已经摘的次数}}

        // 初始化每个果树的第一次摘果子
        for (int i = 1; i <= end; i++) {
            if (f[i] > 0) {
                pq.push({f[i], {i, 1}});
            }
        }

        ll total_fruits = 0;
        // 在剩余时间内尽可能多地摘果子
        while (remain_time > 0 && !pq.empty()) {
            auto [fruits, info] = pq.top();
            pq.pop();

            int tree = info.first;
            int times = info.second;

            total_fruits += fruits;
            remain_time--;

            // 计算下一次摘果子的数量
            ll next_fruits = max(0LL, f[tree] - times * d[tree]);
            if (next_fruits > 0) {
                pq.push({next_fruits, {tree, times + 1}});
            }
        }

        ans = max(ans, total_fruits);
    }

    cout << ans << endl;
    return 0;
}

