int calculateDissatisfaction(long long price) {
    std::string priceStr = std::to_string(price);
    while (!priceStr.empty() && priceStr.back() == '0') {
        priceStr.pop_back();
    }
    int digitCount = priceStr.length();
    if (priceStr.empty()) {
        return 0;
    }
