    while (testCases--) {
        long long leftBound, rightBound;
        std::cin >> leftBound >> rightBound;

        int minDissatisfaction = 20;
        long long bestPrice = rightBound + 1;

        std::vector<long long> powerOfTen(11);
        powerOfTen[0] = 1;
        for (int i = 1; i <= 10; ++i) {
