#include <iostream>
#define ll long long
using namespace std;
ll a[300010],b[300010];
ll n, m;

// 上取整函数
ll ceil(ll x, ll y) {
    return (x + y - 1) / y;
}

// 检查是否能让所有课程的熟练度都达到k
bool check(ll k) {
    // 计算每门课程需要的最少周数
    ll need[300010];
    for (int i = 1; i <= n; i++) {
        need[i] = ceil(k, max(a[i], b[i]));
    }

    // 如果总周数超过M*N，直接返回false
    ll total_need = 0;
    for (int i = 1; i <= n; i++) {
        total_need += need[i];
    }
    if (total_need > m * n) return false;

    // 计算每门课程需要上课的次数
    ll attend[300010];
    for (int i = 1; i <= n; i++) {
        if (a[i] >= b[i]) {
            attend[i] = need[i];
        } else {
            // 计算最优的分配方式
            ll min_attend = 1e18;
            for (ll x = 0; x <= need[i]; x++) {
                ll remain = k - x * a[i];
                if (remain <= 0) {
                    min_attend = min(min_attend, x);
                    break;
                }
                ll y = ceil(remain, b[i]);
                if (x + y <= need[i]) {
                    min_attend = min(min_attend, x);
                }
            }
            attend[i] = min_attend;
        }
    }

    // 检查每周的课程安排是否可行
    ll total_attend = 0;
    for (int i = 1; i <= n; i++) {
        total_attend += attend[i];
    }

    // 每周最多只能上n节课
    return total_attend <= m * n;
}

int main(){
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) cin >> b[i];
    ll left = 0, right = 1e18+1000;
    while (left + 1 < right) {
        ll mid = left + right >> 1;
        if (check(mid)) left = mid;//课时数够，提高要求
        else right = mid;
    }
    // [[[[[[ ))))) 满足课时数"[" 的最大值答案在left
    cout << left;
    return 0;
} 
