    int n;
    cin >> n;
    vector<int> nums(n);

    // 读取输入数组
    for(int i = 0; i < n; i++) {
        cin >> nums[i];
    }

    int maxReach = 0;  // 当前能到达的最远位置
    int current = 0;   // 当前位置

    while(current <= maxReach && current < n) {
        // 更新能到达的最远位置
        maxReach = max(maxReach, current + nums[current]);
        current++;
    }

    // 输出结果（确保不超过数组范围）
    cout << min(maxReach, n-1) << endl;

    return 0;
