C=A+B;

cout<<"A+B="<<A<<"+"<<B<<"="<<C<<endl;

C=A-B;

cout<<"A-B="<<A<<"-"<<B<<"="<<C<<endl;

t=A*B;

cout<<"A*B="<<A<<"*"<<B<<"="<<t<<endl;

