#include<iostream>

#include<cstring>

using namespace std;

class String

{

char *data;

int size;

public:

String( char* s);

operator char* () const;		//把类对象转换成字符串

operator int()const;			//把类对象转换成int类型数值

operator double()const;		//把类对象转换成double类型数值

};

String::String( char* s)

{

size=strlen(s);

data = new char(size+1);

strcpy_s(data,size+1,s);

}

String::operator char* () const

{

return data;

}

String::operator int()const

{

int i, n=0;

for(i=0; i<size; i++)

{

if(data[i]<'0'||data[i]>'9')

{

cout<<"#No int#\n";

exit(0) ;

}

else

{

n*=10;

n+=int(data[i]-'0');

}

}

return n;

}

String::operator double()const

{

double x=0, p=1;

int i, point=size;

for(i=0; i<size; i++)

{

if((data[i]<'0'||data[i]>'9')&&data[i]!='.')

{

cout<<"#No double#\n";

exit(0) ;

}

if(data[i]=='.') point=i;	//记录小数点位置

if(i<point)			//处理整数部分

{

x*=10;

x+=int(data[i]-'0');

}

if(i>point)			//处理小数部分

{

p/=10;

x+=int(data[i]-'0')*p;

}

}

return x;

}

