阅读以下程序，分析下面语句序列中每个字符“∗”和“&”的含义，并写出输出结果。

#include <iostream>
using namespace std;
int main()
{  int a=10, b=20;
   int *p=&a, *q=&b;
   *p =*p* *q;
   int & ra = a;
   ra=a;
   int *& rt = q;
   *rt = 30;
   cout<<"a="<<a<<"\nb="<<b<<"\n*p="<<*p<<"\n*q="<<*q
            <<"\nra="<<ra<<"\n*rt="<<*rt<<endl;
}

【解答】

int main()
{

int a=10, b=20;
  int ∗p = &a, ∗q = &b;
//*为指针类型说明符，&是取址运算符
  ∗p = ∗p ∗ ∗q;
//第1、2、4 个*为间址运算符，第3 个是算数乘运算符
  int & ra = a;
//&是引用说明符
  ra=a;
  int ∗ & rt = q;
//*指针说明符，&引用说明符
  ∗rt = 30;
//*间址运算符
  cout<<"a="<<a<<"\nb="<<b<<"\n∗p="<<∗p<<"\n∗q="<<∗q
       <<"\nra="<<ra<<"\n∗rt="<<∗rt<<endl;      //字符串中的*是字符，其他是间址运算符
}
