cout<<"a 的地址："<<&a<<endl;

cout<<"ra 的值："<<ra<<endl;

cout<<"ra 的地址："<<&ra<<endl;

cout<<"pa 所指向的变量的值："<<*pa<<endl;

cout<<"pa 的地址："<<pa<<endl;
}

4．数据对象在C++中有什么不同的访问方式？请编写一个程序验证之。
【解答】

数据对象在C++中的访问方式有：名访问，引用（别名）访问，间址访问。
验证程序：

#include<iostream>
using namespace std;

int main()

{

int a;

cout<<"a=";

cin>>a;

a=a+5;
//名访问

cout<<&a<<endl;
//输出变量地址

cout<<*(&a)<<endl;
//地址访问，输出变量值

int *pa=&a;
//说明指针变量，指向变量a

cout<<*pa<<endl;
//间址访问，输出变量值

int &ra=a;
//ra 是a 的引用

cout<<ra<<endl;
//引用访问，输出变量a 的值
}

