【解答】

#include<iostream>

using namespace std;

typedef void orderFun (int &, int&,int&);

orderFun sequence, retrograde;

int main()

{

int a,b,c;

int t1,t2,t3;

orderFun *pf;
//说明函数指针

cout<<"请输入3个不相等的整数：";

cin>>a>>b>>c;

t1=a;  t2=b;  t3=c;

pf=sequence;
//获取函数地址

pf(t1,t2,t3);
//调用函数

cout<<"顺序输出："<<t1<<"  "<<t2<<"  "<<t3<<endl;

t1=a;  t2=b;  t3=c;

pf=retrograde;

pf(t1,t2,t3);

cout<<"逆序输出："<<t1<<"  "<<t2<<"  "<<t3<<endl;

}

void sequence (int &x, int &y, int &z)

{

int t;

if( x>y ) { t=x;  x=y;  y=t; }

if( x>z ) { t=x;  x=z;  z=t; }

if( y>z ) { t=y;  y=z;  z=t; }

}

void retrograde (int &x, int &y, int &z)

{

int t;

if( x<y ) { t=x;  x=y;  y=t; }

if( x<z ) { t=x;  x=z;  z=t; }

if( y<z ) { t=y;  y=z;  z=t; }

}

