【解答】

void swap (int &a, int &b)

{

a=a^b;

b=a^b;

a=a^b;

}

void swap(double &x, double &y)

{

int*xp,*yp;

xp = (int*)(&x);

yp = (int*)(&y);

*xp=(*xp)^*(yp);     *yp=(*xp)^(*yp);     *xp=(*xp)^(*yp);

xp++;   yp++;

*xp=(*xp)^*(yp);     *yp=(*xp)^(*yp);     *xp=(*xp)^(*yp);

}

