if (p->next == NULL)

{

pd = p;
      //待删除结点

q->next = NULL;

delete pd;

goto L3;

}

else

{

pd = p;
      //待删除结点

q->next = p->next;

delete pd;

p = q->next;

continue;

}

q = p;

p = p->next;

}

L3: return (head);

}

