{

public:

line( double u, double v )

{

a=u;  b=v;

}

void print()

{

cout<<"y="<<a<<"x+"<<b<<endl;

}

friend point setpoint(line &l1,line &l2);

private:

double a, b;

};

point setpoint( line &l1, line &l2 )

{

