#include<iostream>

using namespace std;
class RMB
{
int yuan, jiao, fen ;
bool mark;
 public:
RMB(int y, int j, int f, bool mark=false);
RMB(double x=0);
operator double()const;
friend istream& operator>>(istream&, RMB&);
friend ostream& operator<<(ostream&, RMB);
