RMB::RMB(int y, int j, int f, bool m )
{
   yuan=y; jiao=j; fen=f; mark=m;
}
RMB::RMB(double x)
{
 if(x<0)
 {
    mark=true; x=-x;
 }
 else
    mark=0;
 int n=int((x+0.005)*100);
 yuan=n/100;
 jiao=(n-yuan*100)/10;
 fen=n%10;
}

RMB::operator double()const
{
 double x=yuan+jiao/10.0+fen/100.0;
 if(mark) x=-x;
 return x;
}
