#include <iostream>

#include <cstdio>

using namespace std;

void X_Draw(const int &, const int *n);

int main() {

int T;

cin >> T;

int n[T];

for (int i = 0; i < T; i++)

cin >> n[i];

X_Draw(T, n);

return 0;

}

void X_Draw(const int &T, const int *n) {

for (int t = 0; t < T; ++t){

int len = n[t];

for (int i = 0; i < len; ++i){

for (int j = 0; j < len; ++j){

if ((j == i) || ((i + j) == (len - 1))){

printf("X");

}

else{

//右半部分空格不需要打印(即右半边i<j区域)，否则PE输出格式错误

//printf(" ");

//左半边空格打印

if(i*2 <len-1){

if(i+j<len){

printf(" ");

}

}

//右半边上下两个三角形区域空格打印

else{

if( i>=j ){

printf(" ");

}

}

}

}

printf("\n");

}

}

}

F  孪生数字

Description

如果一个整数，乘以2之后，得到的另一个整数中的每一位的数字以及出现的次数都与原来的数字相同，只是排序不同，那么我们说这两个数是孪生数字。比如整数123456789，乘以2之后得到246913578，两个整数中每一位出现的次数都一致，现在输入一个整数，判断是不是孪生数字。

Input

输入第一行为整数T，代表接下来的T组数据，接着输入T个整数，每个整数都不会超过20位。

Output

如果该整数是孪生数字，则输出Yes，否则输出No，每组整数的结果用换行符隔开。

Sample Input

3

123456789

1234567899

11111111221122111232

Sample Output

Yes

Yes

No

