#include<stdio.h>

#include<iostream>

#include<string>

using namespace std;

int main()

{

int ans[10]={0};

char num1[22]={0};

char num2[22]={0};

int T;

cin>>T;

while(T--)

{

cin>>num1;

int i,di = 0, jin = 0,ji = 0;

for (i = 21; num1[i] == 0; i--);

for ( ; i >= 0; i -- )

{

ji = (num1[i] - '0') * 2; //ji是翻倍后的结果

ans[num1[i] - '0'] ++;//ans对原数相应位的个数++

di = ji % 10;//*2后的当前位的数字

num2[i] = di + jin + '0';

ans[num2[i] - '0'] --;//ans对结果数的相应位的个数--

jin = (ji + jin) / 10;

}

if (jin != 0) ans[jin] ++;

for (i = 1; i < 10; i++)if (ans[i] != 0)break;//判断ans是否全部都为0，若是，则说明原数和结果数是相同的排列

if (i == 10)

{

cout<<"Yes"<<endl;

}

else

{

cout<<"No"<<endl;

}

for(int k = 0;k<22;k++)

{

num1[k] = 0;

num2[k] = 0;

if(k<10)

{

ans[k] = 0;

}

}

}

}

